{"list":[{"type":"eventStartConditional","center":{"x":0,"y":240},"triggerType":"afterRecordSaved","isInterrupting":false,"id":"cm1startevt","text":"After community meeting saved","description":null,"conditionsAll":[],"conditionsAny":[{"comparison":"equals","subjectType":"value","cid":0,"fieldToCompare":"autoSummaryStatus","type":"any","value":"requested"}],"conditionsFormula":null},{"type":"task","center":{"x":180,"y":240},"id":"cm2setrecrd","text":"set $$meetingRecord","actionList":[{"formula":"
// Fetch attributes of the community meeting record.
$meetingNotes = record\attribute('CCommunityMeetingData', id, 'meetingNotes');
$meetingID = record\attribute('CCommunityMeetingData', id, 'meetingID');
$createdAt = record\attribute('CCommunityMeetingData', id, 'createdAt');
$dateOfMeeting = record\attribute('CCommunityMeetingData', id, 'dateOfMeeting');
$methodOfCollection = record\attribute('CCommunityMeetingData', id, 'methodOfCollection');
$format = record\attribute('CCommunityMeetingData', id, 'format');
$project = record\attribute('CCommunityMeetingData', id, 'project');
$location = record\attribute('CCommunityMeetingData', id, 'location');
$ageGroup = record\attribute('CCommunityMeetingData', id, 'ageGroup');
$gender = record\attribute('CCommunityMeetingData', id, 'gender');
$groupSize = record\attribute('CCommunityMeetingData', id, 'groupSize');

// The API declares meetingNotes, id and metadata.created as non-nullable
// strings; json\encode renders an unset Espo field as null, and null is a 422.
ifThen($meetingNotes == null, $meetingNotes = '');
ifThen($meetingID == null, $meetingID = '');
ifThen($createdAt == null, $createdAt = '');

// Every metadata value is typed as a string server-side, so a date or numeric
// Espo field has to be coerced. The remaining keys are nullable and are left
// as they are.
ifThen($dateOfMeeting != null, $dateOfMeeting = string\concatenate($dateOfMeeting, ''));
ifThen($groupSize != null, $groupSize = string\concatenate($groupSize, ''));

$metadata = object\create();
$metadata['created'] = $createdAt;
$metadata['dateOfMeeting'] = $dateOfMeeting;
$metadata['methodOfCollection'] = $methodOfCollection;
$metadata['format'] = $format;
$metadata['project'] = $project;
$metadata['location'] = $location;
$metadata['ageGroup'] = $ageGroup;
$metadata['gender'] = $gender;
$metadata['groupSize'] = $groupSize;

$meetingRecord = object\create();
$meetingRecord['id'] = $meetingID;
$meetingRecord['meetingNotes'] = $meetingNotes;
$meetingRecord['metadata'] = $metadata;

// Espo's internal record id is the path segment of the record detail view,
// so it is what espo_feedback_base_url gets joined with for the hyperlink.
$meetingRecord['url_id'] = id;

// Never assemble the payload with string\concatenate: a line break, tab,
// quote or backslash in the meeting notes then produces invalid JSON and the
// request dies in the parser with 422 json_invalid (issue #245).
$$meetingRecord = $meetingRecord;
","cid":0,"id":"cmfset00001","type":"executeFormula"}],"description":null},{"type":"gatewayExclusive","center":{"x":340,"y":240},"id":"cm3gateway0","text":"Check if summarize is 'requested' or 'queued'","defaultFlowId":"cmflowgate2end","flowList":[{"id":"cmflowgate2combine","conditionsAll":[],"conditionsAny":[{"comparison":"equals","subjectType":"value","cid":0,"fieldToCompare":"autoSummaryStatus","type":"any","value":"requested"},{"comparison":"equals","subjectType":"value","cid":1,"fieldToCompare":"autoSummaryStatus","type":"any","value":"queued"}],"conditionsFormula":null}],"description":null},{"type":"task","center":{"x":500,"y":240},"id":"cm4combine0","text":"combine $$motherPayload","actionList":[{"formula":"$payload = object\create();
$payload['community_meeting_record'] = $$meetingRecord;

// Optional: mentions of the record id in the summary become a markdown link
// back to this record. Left out entirely when the secret is not set.
$espoBaseUrl = ext\appSecret\get('QFA_ESPO_MEETING_BASE_URL');
ifThen($espoBaseUrl != null, $payload['espo_feedback_base_url'] = $espoBaseUrl);

$motherPayload = json\encode($payload);

$baseUrl = ext\appSecret\get('QFA_API_BASE_URL');
$urlSummarizeMeeting = string\concatenate($baseUrl, '/v1/summarize-community-meeting');
","cid":0,"id":"cmfcomb00001","type":"executeFormula"},{"formula":"// update status
autoSummaryStatus = 'processing';
","cid":1,"id":"cmfcomb00002","type":"executeFormula"}],"description":null},{"type":"task","center":{"x":680,"y":240},"id":"cm5sendreq0","text":"summarize community meeting","actionList":[{"requestType":"POST","contentType":"application/json","content":"{}","requestUrl":"{$$urlSummarizeMeeting}","headers":["Authorization: Bearer {#secrets.QFA_API_KEY}"],"contentVariable":"$motherPayload","cid":0,"id":"cmhttp000001","type":"sendRequest"},{"formula":"$response = $_lastHttpResponseBody;

generatedSummary = json\retrieve($response, 'summary');
generatedTitle = json\retrieve($response, 'title');
autoSummaryStatus = 'completed';
